import React from 'react';
import { isElement } from 'react-is';

import { TrackAtom } from '../components/TrackAtom.js';

/**
 * Extract all visible TrackAtom components,
 * checking deeper in case they are grouped into a wrapper component
 *
 * @param elements -
 */
export function extractVisibleTracks(
  elements: React.ReactNode,
): React.ReactNode {
  const elementsArray: React.ReactNode[] = [];
  React.Children.forEach(elements, (element) => {
    if (isElement(element)) {
      if (element.type === TrackAtom) {
        if (!element.props.hidden) {
          // Search first for the TrackAtom
          elementsArray.push(element);
        }
      } else if (element.props.children) {
        // Check one level deep if not present
        return extractVisibleTracks(element.props.children);
      }
    }
  });

  return elementsArray;
}
